"use client";

import { motion } from "motion/react";
import { useId, useMemo } from "react";
import { chartCssVars, useChartStable } from "./chart-context";
import {
  computeWeekendIndexRuns,
  computeWeekendRanges,
  type DateRangeAlign,
  DEFAULT_WEEKEND_DAYS,
} from "./date-ranges";
import { type PatternPresetId, renderPatternPreset } from "./pattern-preset";
import { type CategorySlots, useCategorySlots } from "./use-category-slots";
import { isReferenceAreaVisiblePhase } from "./y-domain-utils";

export type WeekendsFillType = "pattern" | "solid";

export interface WeekendsProps {
  /**
   * Days that count as weekend, as `Date#getDay()` numbers (0 = Sunday).
   * Default: `[6, 0]` (Saturday + Sunday). Use `[5, 6]` for Fri–Sat locales.
   */
  weekendDays?: readonly number[];
  /** Default: `"pattern"` (diagonal stripes). */
  fillType?: WeekendsFillType;
  /** Band / stripe colour. Default: `var(--chart-foreground-muted)` */
  fill?: string;
  /** Default: 0.45 for `pattern`, 0.08 for `solid`. */
  fillOpacity?: number;
  /** Pattern preset when `fillType` is `"pattern"`. Default: `"diagonal"` */
  pattern?: PatternPresetId;
  /** Default: 1.5 */
  patternScale?: number;
  /** Default: 1 */
  patternStrokeWidth?: number;
  /**
   * `"calendar"` shades midnight → midnight; `"centered"` shifts half a day so
   * daily points / columns sit mid-band. `"auto"` picks `"centered"` when the
   * chart has `SeriesBar` columns anchored at midnight. Band (bar) scales
   * always shade whole columns.
   * Default: `"auto"`
   */
  align?: "auto" | DateRangeAlign;
  /** Use UTC day boundaries. Default: false (local time) */
  utc?: boolean;
  /** Skip rendering when one day is narrower than this many pixels. Default: 2 */
  minDayWidth?: number;
  /**
   * Band (bar chart) scales only — data key holding each row's date. Default:
   * first field holding a `Date` or `"YYYY-MM-DD"` string.
   */
  dateKey?: string;
  className?: string;
}

interface WeekendRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

const DAY_MS = 24 * 60 * 60 * 1000;
const ENTER_FADE_MS = 420;

/** Center bands on midnight-anchored columns; noon-anchored columns already sit mid-day. */
function resolveAutoAlign(
  hasColumns: boolean,
  firstX: Date | undefined,
  utc: boolean
): DateRangeAlign {
  if (!(hasColumns && firstX) || Number.isNaN(firstX.getTime())) {
    return "calendar";
  }
  const hours = utc ? firstX.getUTCHours() : firstX.getHours();
  const minutes = utc ? firstX.getUTCMinutes() : firstX.getMinutes();
  return hours === 0 && minutes === 0 ? "centered" : "calendar";
}

interface PlotSize {
  innerWidth: number;
  innerHeight: number;
}

function bandScaleWeekendRects(
  slots: CategorySlots,
  weekendDays: number[],
  utc: boolean,
  minDayWidth: number,
  { innerWidth, innerHeight }: PlotSize
): WeekendRect[] {
  if (slots.step < minDayWidth) {
    return [];
  }
  const extent = slots.axis === "x" ? innerWidth : innerHeight;
  return computeWeekendIndexRuns(slots.dates, { weekendDays, utc }).flatMap(
    ([first, last]) => {
      const start = Math.max(0, slots.slotStart(first));
      const end = Math.min(extent, slots.slotStart(last) + slots.step);
      if (end <= start) {
        return [];
      }
      return slots.axis === "x"
        ? [{ x: start, y: 0, width: end - start, height: innerHeight }]
        : [{ x: 0, y: start, width: innerWidth, height: end - start }];
    }
  );
}

function timeScaleWeekendRects(
  xScale: (value: Date) => number,
  weekendDays: number[],
  utc: boolean,
  align: DateRangeAlign,
  minDayWidth: number,
  { innerWidth, innerHeight }: PlotSize
): WeekendRect[] {
  const [d0, d1] = (xScale as unknown as { domain: () => Date[] }).domain();
  if (!(d0 && d1)) {
    return [];
  }
  const spanMs = Math.abs(d1.getTime() - d0.getTime());
  if (spanMs <= 0 || (innerWidth * DAY_MS) / spanMs < minDayWidth) {
    return [];
  }
  return computeWeekendRanges(d0, d1, { weekendDays, utc, align }).flatMap(
    ({ start, end }) => {
      const a = xScale(start);
      const b = xScale(end);
      const x0 = Math.max(0, Math.min(a, b));
      const x1 = Math.min(innerWidth, Math.max(a, b));
      return x1 > x0
        ? [{ x: x0, y: 0, width: x1 - x0, height: innerHeight }]
        : [];
    }
  );
}

/**
 * Shades weekend spans behind the series on date x axes — time scales
 * (line / area / composed) and band scales (bar columns). Only visible spans
 * render, so brush zoom and long ranges stay cheap.
 */
export function Weekends({
  weekendDays = DEFAULT_WEEKEND_DAYS,
  fillType = "pattern",
  fill = chartCssVars.foregroundMuted,
  fillOpacity,
  pattern = "diagonal",
  patternScale = 1.5,
  patternStrokeWidth = 1,
  align = "auto",
  utc = false,
  minDayWidth = 2,
  dateKey,
  className,
}: WeekendsProps) {
  const {
    innerWidth,
    innerHeight,
    xScale,
    barScale,
    composedBarDataKeys,
    data,
    xAccessor,
    chartPhase,
    enterTransition,
  } = useChartStable();
  const slots = useCategorySlots(dateKey);
  const patternId = `chart-weekends-pattern-${useId().replace(/:/g, "")}`;

  const firstRow = data[0];
  const resolvedAlign: DateRangeAlign =
    align === "auto"
      ? resolveAutoAlign(
          (composedBarDataKeys?.length ?? 0) > 0,
          firstRow && !barScale ? xAccessor(firstRow) : undefined,
          utc
        )
      : align;
  const weekendKey = weekendDays.join(",");

  const rects = useMemo<WeekendRect[]>(() => {
    const days = weekendKey ? weekendKey.split(",").map(Number) : [];
    if (innerWidth <= 0 || innerHeight <= 0) {
      return [];
    }
    if (slots) {
      return bandScaleWeekendRects(slots, days, utc, minDayWidth, {
        innerWidth,
        innerHeight,
      });
    }
    if (barScale) {
      // Band scale without parseable dates — nothing to shade.
      return [];
    }
    return timeScaleWeekendRects(
      xScale,
      days,
      utc,
      resolvedAlign,
      minDayWidth,
      {
        innerWidth,
        innerHeight,
      }
    );
  }, [
    weekendKey,
    innerWidth,
    innerHeight,
    slots,
    barScale,
    xScale,
    utc,
    resolvedAlign,
    minDayWidth,
  ]);

  const usesPattern = fillType === "pattern" && pattern !== "none";
  const patternNode = useMemo(
    () =>
      usesPattern
        ? renderPatternPreset(pattern, patternId, {
            color: fill,
            scale: patternScale,
            strokeWidth: patternStrokeWidth,
          })
        : null,
    [usesPattern, pattern, patternId, fill, patternScale, patternStrokeWidth]
  );

  if (rects.length === 0) {
    return null;
  }

  const opacity = fillOpacity ?? (usesPattern ? 0.45 : 0.08);
  const rectFill = patternNode ? `url(#${patternId})` : fill;
  const visible = isReferenceAreaVisiblePhase(chartPhase);
  const fadeTransition =
    enterTransition && typeof enterTransition === "object"
      ? enterTransition
      : { duration: ENTER_FADE_MS / 1000, ease: "easeOut" as const };

  return (
    <motion.g
      animate={{ opacity: visible ? 1 : 0 }}
      aria-hidden="true"
      className={className ?? "chart-weekends"}
      initial={{ opacity: 0 }}
      transition={fadeTransition}
    >
      {patternNode}
      <g fill={rectFill} opacity={opacity}>
        {rects.map((rect) => (
          <rect
            height={rect.height}
            key={`${rect.x}:${rect.y}`}
            width={rect.width}
            x={rect.x}
            y={rect.y}
          />
        ))}
      </g>
    </motion.g>
  );
}

Weekends.displayName = "Weekends";

export default Weekends;

/** Day-of-week numbers as returned by `Date#getDay()` (0 = Sunday … 6 = Saturday). */
export type WeekdayIndex = 0 | 1 | 2 | 3 | 4 | 5 | 6;

/** Saturday + Sunday. */
export const DEFAULT_WEEKEND_DAYS: readonly WeekdayIndex[] = [6, 0];

/**
 * How a highlighted day maps onto the x axis.
 * - `"calendar"` — midnight to midnight (points at 00:00 sit on the band's left edge)
 * - `"centered"` — shifted half a day earlier so each day's point / column sits in the middle
 */
export type DateRangeAlign = "calendar" | "centered";

export interface DateRange {
  start: Date;
  end: Date;
}

export interface ComputeWeekendRangesOptions {
  weekendDays?: readonly number[];
  /** Use UTC day boundaries instead of local time. Default: false */
  utc?: boolean;
  align?: DateRangeAlign;
  /** Bail out (return `[]`) when the domain spans more days than this. Default: 20_000 */
  maxDays?: number;
}

const HALF_DAY_MS = 12 * 60 * 60 * 1000;
const DAY_MS = 24 * 60 * 60 * 1000;

function startOfDay(date: Date, utc: boolean): Date {
  return utc
    ? new Date(
        Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate())
      )
    : new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

/** Next midnight — calendar arithmetic so DST days stay aligned. */
function addDays(date: Date, days: number, utc: boolean): Date {
  return utc
    ? new Date(
        Date.UTC(
          date.getUTCFullYear(),
          date.getUTCMonth(),
          date.getUTCDate() + days
        )
      )
    : new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

export function isWeekendDate(
  date: Date,
  weekendDays: readonly number[] = DEFAULT_WEEKEND_DAYS,
  utc = false
): boolean {
  const day = utc ? date.getUTCDay() : date.getDay();
  return weekendDays.includes(day);
}

/**
 * Contiguous weekend spans that intersect `[domainStart, domainEnd]`, clipped
 * to the domain. Consecutive weekend days merge into one range (Sat + Sun →
 * one span; Fri + Sat locales work the same way).
 */
export function computeWeekendRanges(
  domainStart: Date,
  domainEnd: Date,
  options: ComputeWeekendRangesOptions = {}
): DateRange[] {
  const {
    weekendDays = DEFAULT_WEEKEND_DAYS,
    utc = false,
    align = "calendar",
    maxDays = 20_000,
  } = options;

  let lo = domainStart.getTime();
  let hi = domainEnd.getTime();
  if (!(Number.isFinite(lo) && Number.isFinite(hi))) {
    return [];
  }
  if (lo > hi) {
    [lo, hi] = [hi, lo];
  }
  if (weekendDays.length === 0 || (hi - lo) / DAY_MS > maxDays) {
    return [];
  }

  const shift = align === "centered" ? HALF_DAY_MS : 0;
  const ranges: DateRange[] = [];
  let runStart: number | null = null;

  // Start one day early so a centered span (or a span already in progress at
  // the domain start) is still picked up.
  let day = addDays(startOfDay(new Date(lo + shift), utc), -1, utc);
  while (day.getTime() - shift <= hi) {
    const next = addDays(day, 1, utc);
    if (isWeekendDate(day, weekendDays, utc)) {
      if (runStart === null) {
        runStart = day.getTime() - shift;
      }
    } else if (runStart !== null) {
      pushClipped(ranges, runStart, day.getTime() - shift, lo, hi);
      runStart = null;
    }
    day = next;
  }
  if (runStart !== null) {
    pushClipped(ranges, runStart, day.getTime() - shift, lo, hi);
  }
  return ranges;
}

function pushClipped(
  ranges: DateRange[],
  start: number,
  end: number,
  lo: number,
  hi: number
) {
  const s = Math.max(start, lo);
  const e = Math.min(end, hi);
  if (e > s) {
    ranges.push({ start: new Date(s), end: new Date(e) });
  }
}

/**
 * Inclusive `[first, last]` index runs of consecutive weekend rows — for band
 * (category) scales where each row is one column. Rows with no date break a run.
 */
export function computeWeekendIndexRuns(
  dates: ReadonlyArray<Date | null | undefined>,
  options: Pick<ComputeWeekendRangesOptions, "weekendDays" | "utc"> = {}
): [number, number][] {
  const { weekendDays = DEFAULT_WEEKEND_DAYS, utc = false } = options;
  const runs: [number, number][] = [];
  let runStart = -1;
  dates.forEach((date, index) => {
    const weekend =
      date != null &&
      !Number.isNaN(date.getTime()) &&
      isWeekendDate(date, weekendDays, utc);
    if (weekend) {
      if (runStart < 0) {
        runStart = index;
      }
    } else if (runStart >= 0) {
      runs.push([runStart, index - 1]);
      runStart = -1;
    }
  });
  if (runStart >= 0) {
    runs.push([runStart, dates.length - 1]);
  }
  return runs;
}

const ISO_DATE_ONLY = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Coerce a user date-ish value to a valid `Date` (or `null`). Date-only ISO
 * strings (`"2024-01-06"`) parse as local midnight, not UTC, so the weekday
 * matches the calendar date.
 */
export function toValidDate(value: unknown): Date | null {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }
  if (typeof value === "string") {
    const match = ISO_DATE_ONLY.exec(value.trim());
    if (match) {
      return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    }
  }
  if (typeof value === "number" || typeof value === "string") {
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  return null;
}

/**
 * Key of the first field in `row` holding a `Date` (or a date-only ISO string).
 * Used to find dates on band-scale (bar) charts whose context only exposes
 * category labels.
 */
export function detectDateKey(
  row: Record<string, unknown> | undefined
): string | null {
  if (!row) {
    return null;
  }
  for (const [key, value] of Object.entries(row)) {
    if (value instanceof Date) {
      return key;
    }
    if (typeof value === "string" && ISO_DATE_ONLY.test(value.trim())) {
      return key;
    }
  }
  return null;
}

/** Index of the first row whose date is on or after `target`; `-1` when none. */
export function firstIndexOnOrAfter(
  dates: ReadonlyArray<Date | null | undefined>,
  target: Date
): number {
  const t = target.getTime();
  return dates.findIndex((date) => date != null && date.getTime() >= t);
}

"use client";

import { useMemo } from "react";
import { useChartStable } from "./chart-context";
import { detectDateKey, toValidDate } from "./date-ranges";

export interface CategorySlots {
  /** Per-row date (null when the row has no parseable date). */
  dates: (Date | null)[];
  /** Leading pixel edge of each row's slot, including half the inner padding. */
  slotStart: (index: number) => number;
  /** Full slot size (`bandwidth + inner padding`). */
  step: number;
  /** `"x"` for vertical bars (columns), `"y"` for horizontal bars. */
  axis: "x" | "y";
}

/**
 * Date lookup for band (category) scales — bar charts expose only category
 * labels in context, so read dates from `dateKey` (auto-detected when omitted).
 * Returns `null` on time / linear scales.
 */
export function useCategorySlots(dateKey?: string): CategorySlots | null {
  const { barScale, barXAccessor, data, orientation } = useChartStable();

  return useMemo(() => {
    if (!(barScale && barXAccessor)) {
      return null;
    }
    const key = dateKey ?? detectDateKey(data[0]);
    const dates = data.map((row) => (key ? toValidDate(row[key]) : null));
    const step = barScale.step();
    const gap = step - barScale.bandwidth();
    return {
      dates,
      step,
      axis: orientation === "horizontal" ? "y" : "x",
      slotStart: (index: number) => {
        const row = data[index];
        const start = row ? barScale(barXAccessor(row)) : undefined;
        return (start ?? 0) - gap / 2;
      },
    };
  }, [barScale, barXAccessor, data, orientation, dateKey]);
}
